    seat_centers = [s.horizontal_center for s in seat_patches]
    min_distance = float('inf')
    closest_seat = None
    for seat in blue_seats:
        for child in child_patches:
            distance_to_child = abs(seat.horizontal_center - child.horizontal_center)
            if distance_to_child < min_distance:
                min_distance = distance_to_child
                closest_seat = seat
    return closest_seat

